items.text:
body {
	background-color: #bde0c8;
	font-family: Arial, sans-serif;
}

#intro-screen {
	text-align: center;
	margin-top: 100px;
}

#intro-screen h1 {
	font-size: 50px;
	color: #3f3f3f;
}

#intro-screen p {
	font-size: 20px;
	color: #3f3f3f;
	margin-bottom: 50px;
}

#start-button {
	background-color: #3f3f3f;
	color: #ffffff;
	border: none;
	padding: 10px 20px;
	font-size: 20px;
	cursor: pointer;
}

#start-button:hover {
	background-color: #707070;
}

#intro-screen img {
	width: 400px;
	margin-top: 50px;
}

#game-screen {
	display: none;
	background-image: url('island2.jpg');
	background-repeat: no-repeat;
	background-position: center center;
	background-size: cover;
	width: 100%;
	height: 100vh;
}
